import 'package:shopping_list/models/category.dart';

/// Data model representing an individual grocery item.
/// Holds the item's identity, descriptive name, requested quantity, and its category.
class GroceryItem {
  const GroceryItem({
    required this.id,
    required this.name,
    required this.quantity,
    required this.category,
  });

  /// The unique identifier of the item, typically generated by the backend (Firebase Realtime Database key).
  final String id;

  /// The name or description of the grocery item (e.g., 'Milk', 'Bananas').
  final String name;

  /// The number of units of this item to purchase.
  final int quantity;

  /// The category to which this item belongs, containing its display title and color.
  final Category category;
}
